const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '1:1' }];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;

    var m = (metrics && metrics[0]) ? metrics[0] : {};
    var labelW = (typeof m.width === 'number' && m.width > 0) ? m.width
               : (typeof m.w === 'number' && m.w > 0) ? m.w : 34;
    var labelH = (typeof m.height === 'number' && m.height > 0) ? m.height
               : (typeof m.h === 'number' && m.h > 0) ? m.h : 16;

    var padX = Math.max(40, W * 0.12);
    var y = H * 0.62;
    var x0 = padX;
    var x1 = W - padX;
    var xm = (x0 + x1) / 2;
    var tick = 9;

    var seg = visualSdk.polyline([[x0, y], [x1, y]]);
    var tickL = visualSdk.polyline([[x0, y - tick], [x0, y + tick]]);
    var tickM = visualSdk.polyline([[xm, y - tick], [xm, y + tick]]);
    var tickR = visualSdk.polyline([[x1, y - tick], [x1, y + tick]]);

    var labelX = xm;
    var labelY = y - tick - labelH - 14;
    if (labelY < labelH) { labelY = y + tick + labelH + 14; }
    if (labelX - labelW / 2 < 4) { labelX = labelW / 2 + 4; }
    if (labelX + labelW / 2 > W - 4) { labelX = W - labelW / 2 - 4; }

    return {
      schemaVersion: 1,
      sceneId: 'ratio-1-1-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'segment', commands: seg },
        { id: 'tickL', commands: tickL },
        { id: 'tickM', commands: tickM },
        { id: 'tickR', commands: tickR }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'segment', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'tickL', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'tickM', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'tickR', stroke: '#26354a', strokeWidth: 2 },
          {
            type: 'label',
            text: '1:1',
            x: labelX,
            y: labelY,
            fontSize: 18,
            anchor: 'middle',
            baseline: 'alphabetic',
            fill: '#26354a'
          }
        ]
      }
    };
  }
};
